"""Activate the exact reviewed cognition assets through NOX owner maintenance."""

import base64
from hashlib import sha256
import json
import os
from pathlib import Path
import re
import stat
import subprocess
import sys
from types import ModuleType


CIPHER = ''
CIPHER_SHA = 'fa04b6be9fdfad30d3992a129270f32f69bc150ae2fa058e223b3c04582a9323'
BUNDLE_SHA = '02e48ca4cfb8d71a8be2eb4dfeb690544fdab737c048d354a63a7f07861f5799'
KEYS = Path('/root/nox/state/owner-wow-ingress-7015017904')
CERT_SHA = '9788202aecc431b4e1a92beb6790d7cea75f6f3dfccbebc373f029b33ee4f6d2'
EXPECTED = frozenset(('nox_v38_native_context.py', 'nox_v38_s03_native.py',
                      'nox_s03_scoped_pair.py', 'nox_v38_self_model.py'))


def digest(raw):
    return sha256(raw).hexdigest()


def require(condition, reason):
    if not condition:
        raise RuntimeError('HOLD_WOW_RELAY_' + reason)


def trusted_read(path, limit):
    fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK | os.O_CLOEXEC)
    with os.fdopen(fd, 'rb') as handle:
        info = os.fstat(handle.fileno())
        require(stat.S_ISREG(info.st_mode) and info.st_uid == 0 and info.st_nlink == 1
                and info.st_mode & 0o077 == 0 and 0 < info.st_size <= limit, 'KEY_SCOPE')
        return handle.read(limit)


def bundle():
    require(os.geteuid() == 0 and re.fullmatch('[1-9][0-9]{0,19}',
            os.environ.get('NOX_OWNER_REQUEST_ID', '')), 'OWNER')
    for folder in (KEYS, *KEYS.parents):
        mode = folder.lstat()
        require(stat.S_ISDIR(mode.st_mode) and mode.st_uid == 0 and mode.st_mode & 0o022 == 0,
                'DIRECTORY_SCOPE')
    cert = KEYS / 'ingress.pem'
    key = KEYS / 'ingress.key'
    require(digest(trusted_read(cert, 3000)) == CERT_SHA, 'RECIPIENT_PIN')
    trusted_read(key, 6000)
    cipher = base64.b64decode(CIPHER, validate=True)
    require(len(cipher) <= 200000 and digest(cipher) == CIPHER_SHA, 'CIPHER_PIN')
    result = subprocess.run(
        ('/usr/bin/openssl', 'cms', '-decrypt', '-binary', '-inform', 'DER',
         '-recip', str(cert), '-inkey', str(key)), input=cipher, stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL, timeout=8, check=False,
    )
    require(result.returncode == 0 and digest(result.stdout) == BUNDLE_SHA, 'BUNDLE_PIN')
    return json.loads(result.stdout)


def main():
    release = bundle()
    require(set(release['preimage']) == set(release['assets']) == set(release['postimage'])
            == EXPECTED, 'ASSET_SCOPE')
    mod = ModuleType('nox_reviewed_relay_maintenance')
    sys.modules[mod.__name__] = mod
    exec(compile(base64.b64decode(release['control'], validate=True), 'reviewed_control.py', 'exec'),
         mod.__dict__)
    mod.PREIMAGE = release['preimage']
    mod.KEEP.pop('nox_v38_s03_native.py')
    mod.KEEP['nox_v29_chat_bridge.py'] = release['bridge']
    mod.STOP += (Path('/root/nox/state/MEMORY_STOP.flag'),)
    assets = {name: base64.b64decode(data, validate=True) for name, data in release['assets'].items()}
    receipt = mod.activate(payloads=assets, sha256=release['postimage'])
    print('NOX_MAINT_WOW_RELAY_MEMORY_SELF=' + json.dumps(receipt, separators=(',', ':')), flush=True)
    print('NOX_MAINT_REPAIR_COMPLETE=true', flush=True)


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        reason = str(error)
        print('NOX_MAINT_WOW_RELAY_HOLD=' +
              (reason if re.fullmatch(r'HOLD_[A-Z0-9_]{1,120}', reason) else type(error).__name__),
              flush=True)
        raise SystemExit(2)
